inputs = ['hjdxc', 'fyz', 'vbejh', 'bjez', 'eykd']
outputs = ['hjdxc', 'fyz', 'vicihgjh', 'iciziciz', 'hgyicid']

# Let's analyze each transformation
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        print(f"Transforming '{inputs[i]}' to '{outputs[i]}':")
        print(f"  Length change: {len(inputs[i])} -> {len(outputs[i])}")
        print(f"  Diff positions: ", end="")

        # Find differences character by character
        diff_chars = []
        min_len = min(len(inputs[i]), len(outputs[i]))
        for j in range(min_len):
            if inputs[i][j] != outputs[i][j]:
                diff_chars.append((j, inputs[i][j], outputs[i][j]))

        # Check if there are extra characters in output
        if len(outputs[i]) > len(inputs[i]):
            for j in range(len(inputs[i]), len(outputs[i])):
                diff_chars.append((j, '_', outputs[i][j]))

        print(diff_chars)
        print()

